CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND public.has_role(auth.uid(), 'admin'::public.app_role) $$;
CREATE OR REPLACE FUNCTION public.is_admin_v2() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.is_admin() $$;
CREATE OR REPLACE FUNCTION public.is_admin_v3() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.is_admin() $$;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT tablename, policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('courses','categories','course_contents','enrollments','enrollment_requests','profiles','user_roles','reviews','site_settings') LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['courses','categories','course_contents','enrollments','enrollment_requests','profiles','user_roles','reviews','site_settings'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON public.%I FROM anon',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('CREATE POLICY admin_manage ON public.%I FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin())',t); END LOOP; END $$;
GRANT SELECT ON public.courses,public.categories,public.reviews,public.site_settings,public.course_contents TO anon;
CREATE POLICY catalog_read ON public.courses FOR SELECT TO anon,authenticated USING (is_published=true);
CREATE POLICY category_read ON public.categories FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY public_settings ON public.site_settings FOR SELECT TO anon,authenticated USING (key IN ('hero_title','hero_subtitle','bkash_number','contact_whatsapp','contact_facebook','contact_instagram'));
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY update_profile ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE POLICY insert_profile ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY own_enrollment ON public.enrollments FOR SELECT TO authenticated USING (profile_id=auth.uid());
CREATE POLICY own_request ON public.enrollment_requests FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY pending_request ON public.enrollment_requests FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND coalesce(status,'pending')='pending' AND coalesce(payment_status,'pending')='pending');
CREATE POLICY public_free_lessons ON public.course_contents FOR SELECT TO anon,authenticated USING (is_free=true);
CREATE POLICY enrolled_lessons ON public.course_contents FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.enrollments e WHERE e.profile_id=auth.uid() AND e.course_id=course_contents.course_id AND e.status='active'));
CREATE POLICY approved_reviews ON public.reviews FOR SELECT TO anon,authenticated USING (is_approved=true);
CREATE POLICY own_reviews ON public.reviews FOR SELECT TO authenticated USING (profile_id=auth.uid());
CREATE POLICY submit_review ON public.reviews FOR INSERT TO authenticated WITH CHECK (profile_id=auth.uid() AND coalesce(is_approved,false)=false);
CREATE OR REPLACE FUNCTION public.guard_review_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.is_admin() AND coalesce(NEW.is_approved,false) THEN RAISE EXCEPTION 'Only administrators approve reviews'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS guard_review_approval ON public.reviews;
CREATE TRIGGER guard_review_approval BEFORE INSERT OR UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.guard_review_approval();